"""Audit historical directional moneyflow coverage, identity, fields, and structural stability."""
from __future__ import annotations
import argparse,json
from pathlib import Path
import duckdb,pandas as pd
DB_PATH="/srv/bcache-8t/ygguo/duckdb/quant-a50/quant_a50.duckdb";AMOUNTS=["buy_sm_amount","sell_sm_amount","buy_md_amount","sell_md_amount","buy_lg_amount","sell_lg_amount","buy_elg_amount","sell_elg_amount","net_mf_amount"]
def run(glob,out_json,out_md):
 con=duckdb.connect(DB_PATH,read_only=True);source=f"read_parquet('{glob}',union_by_name=true)"
 try:
  total,distinct_keys,min_date,max_date,symbols=con.execute(f"select count(*),count(distinct (trade_date,ts_code)),min(trade_date),max(trade_date),count(distinct ts_code) from {source}").fetchone();nulls={c:con.execute(f"select count(*) from {source} where {c} is null").fetchone()[0] for c in AMOUNTS};nonpositive=con.execute(f"select count(*) from {source} where coalesce(buy_sm_amount,0)+coalesce(sell_sm_amount,0)+coalesce(buy_md_amount,0)+coalesce(sell_md_amount,0)+coalesce(buy_lg_amount,0)+coalesce(sell_lg_amount,0)+coalesce(buy_elg_amount,0)+coalesce(sell_elg_amount,0)<=0").fetchone()[0];formula=con.execute(f"""with x as (select abs(((buy_sm_amount-sell_sm_amount)+(buy_md_amount-sell_md_amount)+(buy_lg_amount-sell_lg_amount)+(buy_elg_amount-sell_elg_amount))-net_mf_amount) diff,(buy_sm_amount+sell_sm_amount+buy_md_amount+sell_md_amount+buy_lg_amount+sell_lg_amount+buy_elg_amount+sell_elg_amount) total from {source}) select quantile_cont(diff,[.5,.95,.99]),max(diff),quantile_cont(diff/nullif(total,0),[.5,.95,.99]),max(diff/nullif(total,0)) from x""").fetchone();yearly=con.execute(f"""select substr(cast(trade_date as varchar),1,4) year_key,count(*) row_count,count(distinct trade_date) date_count,median(daily_rows) median_rows, sum(buy_sm_amount+sell_sm_amount)/sum(buy_sm_amount+sell_sm_amount+buy_md_amount+sell_md_amount+buy_lg_amount+sell_lg_amount+buy_elg_amount+sell_elg_amount) sm_share,sum(buy_md_amount+sell_md_amount)/sum(buy_sm_amount+sell_sm_amount+buy_md_amount+sell_md_amount+buy_lg_amount+sell_lg_amount+buy_elg_amount+sell_elg_amount) md_share,sum(buy_lg_amount+sell_lg_amount)/sum(buy_sm_amount+sell_sm_amount+buy_md_amount+sell_md_amount+buy_lg_amount+sell_lg_amount+buy_elg_amount+sell_elg_amount) lg_share,sum(buy_elg_amount+sell_elg_amount)/sum(buy_sm_amount+sell_sm_amount+buy_md_amount+sell_md_amount+buy_lg_amount+sell_lg_amount+buy_elg_amount+sell_elg_amount) elg_share,median(((buy_lg_amount+buy_elg_amount)-(sell_lg_amount+sell_elg_amount))/nullif(buy_sm_amount+sell_sm_amount+buy_md_amount+sell_md_amount+buy_lg_amount+sell_lg_amount+buy_elg_amount+sell_elg_amount,0)) median_large_net_rate from (select *,count(*) over(partition by trade_date) daily_rows from {source}) group by 1 order by 1""").df();unmatched=con.execute(f"""select count(*) from {source} m left join MarketData d on d.Symbol=substr(m.ts_code,1,6) and d.TradingDay=strptime(cast(m.trade_date as varchar),'%Y%m%d')::date where d.Symbol is null""").fetchone()[0]
  amount_scale=con.execute(f"""select substr(cast(m.trade_date as varchar),1,4) year_key,quantile_cont((m.buy_sm_amount+m.sell_sm_amount+m.buy_md_amount+m.sell_md_amount+m.buy_lg_amount+m.sell_lg_amount+m.buy_elg_amount+m.sell_elg_amount)/nullif(d.Amount,0),[.1,.5,.9]) ratio from {source} m join MarketData d on d.Symbol=substr(m.ts_code,1,6) and d.TradingDay=strptime(cast(m.trade_date as varchar),'%Y%m%d')::date group by 1 order by 1""").df()
 finally:con.close()
 breaks=[]
 for i in range(1,len(yearly)):
  for field in ["sm_share","md_share","lg_share","elg_share"]:
   change=float(yearly.loc[i,field]-yearly.loc[i-1,field])
   if abs(change)>=.05:breaks.append({"from":str(yearly.loc[i-1,"year_key"]),"to":str(yearly.loc[i,"year_key"]),"field":field,"change":change})
 amount_scale_records=[{"year_key":str(row.year_key),"ratio":[float(v) for v in row.ratio]} for row in amount_scale.itertuples(index=False)]
 payload={"study":"a-share-moneyflow-history-audit-v1","source":glob,"identity":{"rows":int(total),"distinct_keys":int(distinct_keys),"duplicate_rows":int(total-distinct_keys),"min_date":str(min_date),"max_date":str(max_date),"symbols":int(symbols)},"null_counts":nulls,"nonpositive_directional_amount":int(nonpositive),"net_formula":{"absolute_quantiles":formula[0],"absolute_max":formula[1],"relative_quantiles":formula[2],"relative_max":formula[3]},"market_join":{"unmatched_rows":int(unmatched),"coverage":1-unmatched/total},"yearly":yearly.to_dict("records"),"bucket_share_breaks_5pp":breaks,"market_amount_scale":amount_scale_records,"decision":{"usable_for_research":total==distinct_keys and max(nulls.values())==0 and unmatched/total<.10,"all_order_direction_usable":False,"large_order_epoch_usable":True,"size_bucket_cross_period_usable":len(breaks)==0,"decision_grade":False},"limitations":["provider-classified buy/sell and order sizes are not exchange tick authority","provider methodology changes are not formally versioned","net_mf is retained for audit only"]};Path(out_json).write_text(json.dumps(payload,ensure_ascii=False,indent=2,default=lambda x:x.item() if hasattr(x,"item") else x)+"\n");lines=["# A股历史有方向成交量数据审计","",f"- rows/distinct/duplicates: {total:,}/{distinct_keys:,}/{total-distinct_keys:,}",f"- coverage: {min_date}—{max_date}；symbols: {symbols}",f"- MarketData join coverage: {payload['market_join']['coverage']:.4%}",f"- null max: {max(nulls.values())}；nonpositive denominator: {nonpositive}",f"- decision: **{'RESEARCH-USABLE' if payload['decision']['usable_for_research'] else 'BLOCKED'}**","","|年|行数|交易日|日截面中位数|小单占比|中单|大单|超大单|大单净流率中位数|","|---|---:|---:|---:|---:|---:|---:|---:|---:|"]
 for r in yearly.itertuples(index=False):lines.append(f"|{r.year_key}|{r.row_count:,}|{r.date_count}|{r.median_rows:.0f}|{r.sm_share:.2%}|{r.md_share:.2%}|{r.lg_share:.2%}|{r.elg_share:.2%}|{r.median_large_net_rate:.3%}|")
 lines += ["",f">=5pp bucket-share breaks: {len(breaks)}",f"All-order directional amount / MarketData Amount median scale: {pd.Series([row['ratio'][1] for row in amount_scale_records]).median():.9f}","","> Large/small order buckets have a 2021→2022 structural break. All-order buy minus sell is mechanically near zero and cannot express direction. Directional research must use large/extra-large imbalance with rolling history reset at the 2022 methodology epoch.",f"> {unmatched:,} rows lack local MarketData joins; directional breadth may use them, but price validation is limited to matched rows.",""];Path(out_md).write_text("\n".join(lines));return payload
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--glob",default="overall/a-share-moneyflow-raw/moneyflow_*.parquet");p.add_argument("--out-json",default="overall/a-share-moneyflow-history-audit.json");p.add_argument("--out-md",default="overall/a-share-moneyflow-history-audit.md");a=p.parse_args(argv);payload=run(a.glob,a.out_json,a.out_md);print(json.dumps(payload["decision"],ensure_ascii=False,indent=2));return 0
if __name__=="__main__":raise SystemExit(main())
